import {
  MeshBasicNodeMaterial,
  Mesh,
  PlaneGeometry,
  Group,
  SpriteMaterial,
  Sprite,
} from 'three/webgpu';
import { texture, vec2, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- Setup texture and atlas region ---
  const tex = ctx.textureLoader(config.assets.imageUrl);
  tex.wrapS = tex.wrapT = 1000; // ClampToEdgeWrapping
  const fullW = tex.image.width;
  const fullH = tex.image.height;
  const regionW = 512;
  const regionH = 320;
  tex.repeat.set(regionW / fullW, regionH / fullH);
  tex.offset.set(0, 1 - regionH / fullH); // flip Y if needed? Usually atlas top-left = (0,1) offset. We'll assume (0,1 - regionH/fullH) for correct orientation.

  // --- Build background plane ---
  const aspect = regionW / regionH;
  const geo = new PlaneGeometry(1, 1 / aspect);
  const mat = new MeshBasicNodeMaterial();
  mat.map = tex;
  mat.transparent = true; // likely has alpha for grain
  mat.needsUpdate = true;

  const plane = new Mesh(geo, mat);

  // --- Build text using fontAtlas ---
  // Use headline size (0.34) and Lora font, weight 400
  const textOptions = {
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.34, // scene units (headline from typography scale)
    align: 'center',
    // other options from ctx.fontAtlas API assumed
  };
  const textMesh = ctx.fontAtlas.createText(config.textContent['headline'], textOptions);
  // Position text slightly above the plane and centered
  textMesh.position.set(0, 0, 0.01);

  // --- Compose group ---
  const group = new Group();
  group.add(plane);
  group.add(textMesh);

  // Apply placement and scale from config
  group.position.set(config.scenePlacement.position[0], config.scenePlacement.position[1], config.scenePlacement.position[2]);
  group.rotation.set(config.scenePlacement.rotation[0], config.scenePlacement.rotation[1], config.scenePlacement.rotation[2]);
  group.scale.set(config.scenePlacement.scale[0], config.scenePlacement.scale[1], config.scenePlacement.scale[2]);

  // --- Billboarding update ---
  group.userData.handlers = {
    update: (camera) => {
      // Make the entire group face the camera (billboard)
      group.lookAt(camera.position);
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geo.dispose();
    mat.dispose();
    tex.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    // Kill any GSAP timelines if present (none here)
  };

  return group;
}
